cat > /tmp/probes/gen.mjs <<'EOF'
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
const lines = fs.readFileSync('/tmp/probes/all.txt','utf8').split('\n').filter(s=>s.length);
const unesc = s => s.replace(/\\(n|t|r|\\)/g, (m,c)=> c==='n'?'\n':c==='t'?'\t':c==='r'?'\r':'\\');
const out = [];
const seen = new Set();
for (const line of lines) {
  const md = unesc(line);
  if (seen.has(md)) continue; seen.add(md);
  fs.writeFileSync('/tmp/probes/scratch_lists.md', md);
  let txt;
  try { txt = execFileSync('node', ['/tmp/pm.mjs','--file','/tmp/probes/scratch_lists.md'], {encoding:'utf8', stdio:['ignore','pipe','ignore']}); }
  catch(e) { console.error('FAIL', JSON.stringify(md)); continue; }
  const g = k => { const m = txt.match(new RegExp('^'+k+'\\s+(.*)$','m')); return m ? JSON.parse(m[1]) : null; };
  const core=g('CORE_JSON'), tables=g('TABLES_JSON'), extra=g('EXTRA_JSON');
  if (core===null || /usage: test11_executable/.test(core)) { console.error('SKIP', JSON.stringify(md)); continue; }
  out.push(JSON.stringify({md, core, tables, extra}));
}
fs.writeFileSync('/tmp/probes/vectors.jsonl', out.join('\n')+'\n');
console.log('wrote', out.length);
EOF
node /tmp/probes/gen.mjs
